        const studentNode = studentNodes[0];
        const name = select('string(name)', studentNode);
        const age = select('string(age)', studentNode);
        const citizenship = select('string(citizenship)', studentNode);

        return {
            name: name,
            age: parseInt(age, 10),
            citizenship: citizenship
        };
    }

    return null;
}
